        private static readonly List<byte[,]> Tables = new List<byte[,]>((NamespaceCount + 1) * 3)
        {
            null, RootMessages, null, AnchorViews, null, null,
            AreaVisualDataViews, AreaVisualDataMessages, null, CarryableObjectViews, null, null,
            CharacterViews, CharacterMessages, CharacterCommands, DeployableViews, DeployableMessages, null,
            null, null, EncounterCommands, EncounterProxyViews, null, null,
            MeldingViews, null, null, MeldingBubbleViews, null, null,
            OutpostViews, null, null, ResourceAreaViews, null, null,
            ResourceNodeViews, null, null, TurretViews, TurretMessages, TurretCommands,
            VehicleViews, VehicleMessages, VehicleCommands, LootStoreExtensionViews, LootStoreExtensionMessages, null
        };
        private static readonly short[][] NsRouteIds = new short[VersionCount][];
        private static readonly Dictionary<long, int> IdToOrdinal = new(24000);
        private static readonly Dictionary<long, int> RouteToView = new(4096);
        private static readonly Dictionary<long, int> RouteToNamespace = new(4096);

        static GssTables()
        {
            Tables[(Ns.Root + 1) * 3 + Kind.Message] = RootMessages;
            Tables[(Ns.Anchor + 1) * 3 + Kind.View] = AnchorViews;
            Tables[(Ns.AreaVisualData + 1) * 3 + Kind.View] = AreaVisualDataViews;
            Tables[(Ns.AreaVisualData + 1) * 3 + Kind.Message] = AreaVisualDataMessages;
            Tables[(Ns.CarryableObject + 1) * 3 + Kind.View] = CarryableObjectViews;
            Tables[(Ns.Character + 1) * 3 + Kind.View] = CharacterViews;
            Tables[(Ns.Character + 1) * 3 + Kind.Message] = CharacterMessages;
            Tables[(Ns.Character + 1) * 3 + Kind.Command] = CharacterCommands;
            Tables[(Ns.Deployable + 1) * 3 + Kind.View] = DeployableViews;
            Tables[(Ns.Deployable + 1) * 3 + Kind.Message] = DeployableMessages;
            Tables[(Ns.Encounter + 1) * 3 + Kind.Command] = EncounterCommands;
            Tables[(Ns.EncounterProxy + 1) * 3 + Kind.View] = EncounterProxyViews;
            Tables[(Ns.Melding + 1) * 3 + Kind.View] = MeldingViews;
            Tables[(Ns.MeldingBubble + 1) * 3 + Kind.View] = MeldingBubbleViews;
            Tables[(Ns.Outpost + 1) * 3 + Kind.View] = OutpostViews;
            Tables[(Ns.ResourceArea + 1) * 3 + Kind.View] = ResourceAreaViews;
            Tables[(Ns.ResourceNode + 1) * 3 + Kind.View] = ResourceNodeViews;
            Tables[(Ns.Turret + 1) * 3 + Kind.View] = TurretViews;
            Tables[(Ns.Turret + 1) * 3 + Kind.Message] = TurretMessages;
            Tables[(Ns.Turret + 1) * 3 + Kind.Command] = TurretCommands;
            Tables[(Ns.Vehicle + 1) * 3 + Kind.View] = VehicleViews;
            Tables[(Ns.Vehicle + 1) * 3 + Kind.Message] = VehicleMessages;
            Tables[(Ns.Vehicle + 1) * 3 + Kind.Command] = VehicleCommands;
            Tables[(Ns.LootStoreExtension + 1) * 3 + Kind.View] = LootStoreExtensionViews;
            Tables[(Ns.LootStoreExtension + 1) * 3 + Kind.Message] = LootStoreExtensionMessages;

            for (int v = 0; v < VersionCount; v++)
            {
                NsRouteIds[v] = new short[NamespaceCount + 1];
                for (int i = 0; i < NsRouteIds[v].Length; i++)
                    NsRouteIds[v][i] = -1;
            }

            for (int i = 0; i < RouteEntries.Length; i += 3)
            {
                int v = RouteEntries[i];
                int routeId = RouteEntries[i + 1];
                int packed = RouteEntries[i + 2];
                int ns = (packed >> 4) - 2;
                int kind = packed & 15;
                if (ns == Ns.Unknown)
                    continue;
                if (kind == Kind.View)
                {
                    byte[,] views = Tables[(ns + 1) * 3 + Kind.View];
                    if (views != null)
                    {
                        for (int m = 0; m < views.GetLength(1); m++)
                        {
                            if (views[v, m] == routeId)
                            {
                                RouteToView[((long)v << 8) | ((long)routeId & 0xFF)] = (ns << 16) | m;
                                break;
                            }
                        }
                    }
                    RouteToNamespace[((long)v << 16) | (((long)routeId & 0xFF) << 8) | (long)Kind.Message] = ns;
                    RouteToNamespace[((long)v << 16) | (((long)routeId & 0xFF) << 8) | (long)Kind.Command] = ns;
                }
                else
                {
                    if (ns == Ns.Root)
                    {
                        NsRouteIds[v][0] = (short)routeId;
                        RouteToNamespace[((long)v << 16) | (((long)routeId & 0xFF) << 8) | (long)Kind.Message] = ns;
                    }
                    else
                    {
                        NsRouteIds[v][ns + 1] = (short)routeId;
                        RouteToNamespace[((long)v << 16) | (((long)routeId & 0xFF) << 8) | (long)Kind.Message] = ns;
                        RouteToNamespace[((long)v << 16) | (((long)routeId & 0xFF) << 8) | (long)Kind.Command] = ns;
                    }
                }
            }

            for (int i = 0; i < RouteEntries.Length; i += 3)
            {
                int v = RouteEntries[i];
                int routeId = RouteEntries[i + 1];
                int packed = RouteEntries[i + 2];
                int ns = (packed >> 4) - 2;
                int kind = packed & 15;
                if (ns == Ns.Unknown)
                    continue;
                // Messages and commands are addressed by the namespace route AND by the view routes
                // of their namespace, so index the message/command tables under both route kinds.
                int firstKind = kind == Kind.View ? Kind.Message : kind;
                int kindCount = ns == Ns.Root ? 1 : 2;
                for (int k = 0; k < kindCount; k++)
                {
                    int tk = k == 0 ? firstKind : Kind.Command;
                    byte[,] ids = Tables[(ns + 1) * 3 + tk];
                    if (ids == null)
                        continue;
                    for (int m = 0; m < ids.GetLength(1); m++)
                    {
                        byte id = ids[v, m];
                        if (id != 0)
                            IdToOrdinal[((long)v << 32) | ((long)tk << 24) | (((long)routeId & 0xFF) << 8) | (long)id] = m;
                    }
                }
            }
        }

        /// Namespace typecode for a version (root is always 0), 255 = the namespace is not routed in that version.
        public static byte GetNamespaceTypecode(GssVersion version, int nsIndex)
        {
            if (nsIndex == Ns.Root) return 0;
            if (nsIndex < 0 || nsIndex >= NamespaceCount) return 255;
            return (byte)NsRouteIds[(int)version][nsIndex + 1];
        }

        /// Wire id of a universal message/command/view in a version, 0 = it does not exist in that version.
        public static byte GetMessageId(GssVersion version, int nsIndex, int kind, int ordinal)
        {
            if (nsIndex < Ns.Root || nsIndex >= NamespaceCount) return 0;
            byte[,] ids = Tables[(nsIndex + 1) * 3 + kind];
            if (ids == null) return 0;
            if (ordinal < 0 || ordinal >= ids.GetLength(1)) return 0;
            return ids[(int)version, ordinal];
        }

        /// Namespace carried by (typecode, kind) in a version, Ns.Unknown = the typecode is not known for that version.
        /// The typecode may be a namespace route or a view route of the namespace.
        public static int FindNamespace(GssVersion version, byte typecode, int kind)
        {
            long key = ((long)(int)version << 16) | (((long)typecode & 0xFF) << 8) | (long)kind;
            return RouteToNamespace.TryGetValue(key, out int nsIndex) ? nsIndex : Ns.Unknown;
        }

        /// Ordinal of the message/command carried by (typecode, messageId) in a version, -1 = unknown id for that version.
        /// The typecode may be a namespace route or a view route of the namespace.
        public static int FindMessage(GssVersion version, byte typecode, int kind, byte messageId)
        {
            long key = ((long)(int)version << 32) | ((long)kind << 24) | (((long)typecode & 0xFF) << 8) | (long)messageId;
            return IdToOrdinal.TryGetValue(key, out int ordinal) ? ordinal : -1;
        }

        /// Ordinal of the view carried by a typecode in a version, -1 = not a view typecode in that version.
        public static int FindView(GssVersion version, byte typecode)
        {
            long key = ((long)(int)version << 8) | ((long)typecode & 0xFF);
            return RouteToView.TryGetValue(key, out int packed) ? (packed & 0xFFFF) : -1;
        }

        /// Namespace and ordinal of the view carried by a typecode in a version, false = not a view typecode in that version.
        public static bool TryFindView(GssVersion version, byte typecode, out int nsIndex, out int ordinal)
        {
            long key = ((long)(int)version << 8) | ((long)typecode & 0xFF);
            if (RouteToView.TryGetValue(key, out int packed))
            {
                nsIndex = packed >> 16;
                ordinal = packed & 0xFFFF;
                return true;
            }
            nsIndex = Ns.Unknown;
            ordinal = -1;
            return false;
        }

        /// Maps a GSS message/command enum type name to its namespace and kind.
        public static bool TryGetMessageEnumInfo(string messageEnum, out int nsIndex, out int kind)
        {
            switch (messageEnum)
            {
                case "GssMessage":
                    nsIndex = Ns.Root;
                    kind = Kind.Message;
                    return true;
                case "GssAreaVisualDataMessage":
                    nsIndex = Ns.AreaVisualData;
                    kind = Kind.Message;
                    return true;
                case "GssCharacterMessage":
                    nsIndex = Ns.Character;
                    kind = Kind.Message;
                    return true;
                case "GssCharacterCommand":
                    nsIndex = Ns.Character;
                    kind = Kind.Command;
                    return true;
                case "GssDeployableMessage":
                    nsIndex = Ns.Deployable;
                    kind = Kind.Message;
                    return true;
                case "GssEncounterCommand":
                    nsIndex = Ns.Encounter;
                    kind = Kind.Command;
                    return true;
                case "GssTurretMessage":
                    nsIndex = Ns.Turret;
                    kind = Kind.Message;
                    return true;
                case "GssTurretCommand":
                    nsIndex = Ns.Turret;
                    kind = Kind.Command;
                    return true;
                case "GssVehicleMessage":
                    nsIndex = Ns.Vehicle;
                    kind = Kind.Message;
                    return true;
                case "GssVehicleCommand":
                    nsIndex = Ns.Vehicle;
                    kind = Kind.Command;
                    return true;
                case "GssLootStoreExtensionMessage":
                    nsIndex = Ns.LootStoreExtension;
                    kind = Kind.Message;
                    return true;
                default:
                    nsIndex = Ns.Unknown;
                    kind = 0;
                    return false;
            }
        }

