        /// Gets the wire ids for a GSS protocol enum in a version.
        /// For views, typecode is the view/controller typecode and messageId is 0.
        /// For messages/commands, typecode is the namespace route's typecode; use the (view, message)
        /// overload for a message sent through a view route.
        public static bool TryGetWireIds<T>(GssVersion version, T protocolEnum, out byte typecode, out byte messageId)
            where T : struct
        {
            if (!(protocolEnum is System.Enum))
            {
                typecode = 0;
                messageId = 0;
                return false;
            }

            if (!TryGetProtocolEnumInfo(typeof(T).Name, out int nsIndex, out int kind))
            {
                typecode = 0;
                messageId = 0;
                return false;
            }

            int ordinal = System.Convert.ToInt32(protocolEnum);

            if (kind == Kind.View)
            {
                typecode = GetMessageId(version, nsIndex, kind, ordinal);
                messageId = 0;
                return typecode != 0;
            }

            typecode = GetNamespaceTypecode(version, nsIndex);
            messageId = GetMessageId(version, nsIndex, kind, ordinal);
            return typecode != 255 && messageId != 0;
        }
        /// Gets the wire ids of a GSS message sent through a view route in a version.
        /// typecode is the view route's typecode, messageId is the message's wire id, false = the view or message does not exist in that version.
        public static bool TryGetWireIds(GssVersion version, GssAreaVisualDataView view, GssAreaVisualDataMessage message, out byte typecode, out byte messageId)
        {
            typecode = GetMessageId(version, Ns.AreaVisualData, Kind.View, (int)view);
            messageId = GetMessageId(version, Ns.AreaVisualData, Kind.Message, (int)message);
            return typecode != 0 && messageId != 0;
        }

