        public static bool TryGetWireIds(GssVersion version, GssVehicleView view, GssVehicleCommand command, out byte typecode, out byte messageId)
        {
            typecode = GetMessageId(version, Ns.Vehicle, Kind.View, (int)view);
            messageId = GetMessageId(version, Ns.Vehicle, Kind.Command, (int)command);
            return typecode != 0 && messageId != 0;
        }

        /// Gets the wire ids of a GSS message sent through a view route in a version.
        /// typecode is the view route's typecode, messageId is the message's wire id, false = the view or message does not exist in that version.
        public static bool TryGetWireIds(GssVersion version, GssLootStoreExtensionView view, GssLootStoreExtensionMessage message, out byte typecode, out byte messageId)
        {
            typecode = GetMessageId(version, Ns.LootStoreExtension, Kind.View, (int)view);
            messageId = GetMessageId(version, Ns.LootStoreExtension, Kind.Message, (int)message);
            return typecode != 0 && messageId != 0;
        }

    }
}
